// Create your User interface here
interface User {
  name: string;
  age: number;
  email: string;
}

// Create your user object here
const user: User = {
  name: 'Alice',
  age: 30,
  email: 'alice@example.com'
};

// Write your manualPick function here
function manualPick(obj: any, keys: string[]) {
  const result: any = {};
  keys.forEach(key => {
    if (key in obj) {
      result[key] = obj[key];
    }
  });
  return result;
}

// Call manualPick and log the result here
const manualResult = manualPick(user, ['name', 'email']);
console.log('Manual pick result:', manualResult);

// Create your UserNameOnly type using Pick here
type UserNameOnly = Pick<User, 'name'>;

// Create your genericPick function signature here
function genericPick<T, K extends keyof T>(obj: T, keys: K[]): Pick<T, K> {
  const result = {} as Pick<T, K>;
  keys.forEach(key => {
    result[key] = obj[key];
  });
  return result;
}

// Call genericPick with user and ['name', 'email'] here
const genericResult = genericPick(user, ['name', 'email']);
console.log('Generic pick result:', genericResult);

